t.script:

(function(){
  // --- Audio & PWA Logic ---
  var ctx, processor, source, mediaStream, recorderNode;
  var buffers = [], recording = false, sampleRate = 0;

  function initAudio(){
    var AudioContext = window.AudioContext || window.webkitAudioContext;
    if (!AudioContext) return;
    ctx = new AudioContext();
    sampleRate = ctx.sampleRate;
  }

  function startRec(){
    if (!ctx) initAudio();
    if (ctx && ctx.state === 'suspended') ctx.resume();
    navigator.mediaDevices.getUserMedia({ audio: true }).then(function(s){
      mediaStream = s;
      source = ctx.createMediaStreamSource(s);
      processor = ctx.createScriptProcessor(4096, 1, 1);
      processor.onaudioprocess = function(e){
        if (!recording) return;
        var ch = e.inputBuffer.getChannelData(0);
        buffers.push(new Float32Array(ch)); 
      };        
      source.connect(processor);
      processor.connect(ctx.destination);   
      recorderNode = processor;
      recording = true;
    }).catch(function(err){ alert('無法存取麥克風: ' + err); });
  }

  function stopRec(){
    if (!recording) return;
    try { recorderNode && recorderNode.disconnect(); } catch(_){}       
    try { mediaStream && mediaStream.getTracks().forEach(function(t){ t.stop(); }); } catch(_){}
    recording = false;
  }

  function mergeBuffers(bufs){
    var length = 0; for (var i=0;i<bufs.length;i++){ length += bufs[i].length; }
    var out = new Float32Array(length); var offset = 0;
    for (var i=0;i<bufs.length;i++){ out.set(bufs[i], offset); offset += bufs[i].length; }
    return out; 
  }

  function encodeWAV(samples, sampleRate){  
    var buffer = new ArrayBuffer(44 + samples.length * 2);
    var view = new DataView(buffer);        
    function writeString(offset, s){ for (var i=0;i<s.length;i++){ view.setUint8(offset+i, s.charCodeAt(i)); } }
    var offset = 0;
    writeString(0, 'RIFF'); view.setUint32(4, 36 + samples.length * 2, true); writeString(8, 'WAVE');
    writeString(12, 'fmt '); view.setUint32(16, 16, true); view.setUint16(20, 1, true); view.setUint16(22, 1, true);
    view.setUint32(24, sampleRate, true); view.setUint32(28, sampleRate * 2, true); view.setUint16(32, 2, true); view.setUint16(34, 16, true);
    writeString(36, 'data'); view.setUint32(40, samples.length * 2, true);
    var pcm = (function(input){
        var buffer = new ArrayBuffer(input.length * 2);
        var view = new DataView(buffer);        
        var offset = 0;
        for (var i=0;i<input.length;i++, offset+=2){
          var s = Math.max(-1, Math.min(1, input[i]));
          view.setInt16(offset, s < 0 ? s * 0x8000 : s * 0x7FFF, true);     
        }
        return view;
    })(samples);     
    var out = new Uint8Array(buffer);       
    var pcmView = new Uint8Array(pcm.buffer);
    out.set(pcmView, 44);
    return new Blob([out], { type: 'audio/wav' });
  }

  // --- UI Logic ---
  var btn = document.getElementById('btn-main-action');
  var status = document.getElementById('status-text');
  var chat = document.getElementById('chat-container');

  function addBubble(text, isUser){
    var row = document.createElement('div');
    row.style.display = 'flex';
    row.style.gap = '12px';
    row.style.maxWidth = '85%';
    row.style.marginBottom = '16px';

    if (isUser) {
        row.style.alignSelf = 'flex-end';
        row.style.flexDirection = 'row-reverse';
        row.innerHTML = '<div style="flex-shrink:0;width:32px;height:32px;background:#3b82f6;border-radius:50%;display:flex;align-items:center;justify-content:center;color:white;font-size:14px;">我</div>' +
                        '<div class="bubble-user" style="padding:12px;font-size:14px;line-height:1.5;">' + text + '</div>';
    } else {
        row.innerHTML = '<div style="flex-shrink:0;width:32px;height:32px;background:linear-gradient(135deg, #ec4899, #8b5cf6);border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:18px;">👩</div>' +
                        '<div class="bubble-ai" style="padding:12px;font-size:14px;line-height:1.5;">' + text + '</div>';
    }
    chat.appendChild(row);
    chat.scrollTop = chat.scrollHeight;
  }

  function handleAudio(blob){
    status.innerText = '正在聆聽...';
    var fd = new FormData(); fd.append('audio', blob, 'voice.wav');

    fetch('/wuchang/voice/transcribe', { method: 'POST', body: fd })
    .then(function(r){ return r.json(); })
    .then(function(j){
        if ((j||{}).ok && (j.text||'').trim()){
            var text = j.text;
            addBubble(text, true);
            status.innerText = '小j 思考中...';

            // Call LLM
            return fetch('/wuchang/llm/generate', { 
                method:'POST', 
                headers:{'Content-Type':'application/json'}, 
                body: JSON.stringify({ prompt: text }) 
            });
        } else {
            status.innerText = '聽不清楚，請再試一次';
            throw new Error('No text recognized');
        }
    })
    .then(function(r){ return r.json(); })
    .then(function(j){
        var p = ((((j||{}).candidates||[{}])[0]||{}).content||{}).parts||[];
        var reply = (p[0]||{}).text || '抱歉，我暫時無法回答。';
        addBubble(reply, false);
        status.innerText = '準備就緒';

        // TTS
        if (window.speechSynthesis){
            var u = new SpeechSynthesisUtterance(reply); 
            u.lang='zh-TW'; 
            window.speechSynthesis.speak(u);
        }
    })
    .catch(function(e){ 
        console.error(e);
        status.innerText = '發生錯誤，請重試';
    });
  }

  // Interaction Events
  function onStart(e){
    e.preventDefault();
    buffers = [];
    startRec();
    btn.classList.add('pulse');
    btn.innerText = '🔴 正在錄音...';
    btn.style.background = '#ef4444';
    status.innerText = '放開按鈕結束錄音';
  }

  function onEnd(e){
    e.preventDefault();
    stopRec();
    btn.classList.remove('pulse');
    btn.innerText = '🎤 按住說話';
    btn.style.background = 'linear-gradient(135deg, #ec4899, #8b5cf6)';
    status.innerText = '處理中...';

    if (buffers.length > 0){
        var merged = mergeBuffers(buffers);
        var blob = encodeWAV(merged, sampleRate);
        handleAudio(blob);
    }
  }

  btn.addEventListener('mousedown', onStart);
  btn.addEventListener('touchstart', onStart);
  btn.addEventListener('mouseup', onEnd);
  btn.addEventListener('touchend', onEnd);

})();
